"""Shared column definitions: UUID primary keys, the event_id foreign key and timestamps."""

import uuid
from datetime import datetime

from sqlalchemy import DateTime, ForeignKey, func, text
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import Mapped, mapped_column


def uuid_pk() -> Mapped[uuid.UUID]:
    """Purpose: random UUID primary key (generated by the app, with a database default)."""
    return mapped_column(
        UUID(as_uuid=True),
        primary_key=True,
        default=uuid.uuid4,
        server_default=text("gen_random_uuid()"),
    )


def event_fk() -> Mapped[uuid.UUID]:
    """Purpose: event_id column (RLS key, indexed, deleted with the event)."""
    return mapped_column(
        UUID(as_uuid=True),
        ForeignKey("events.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )


def created_at() -> Mapped[datetime]:
    """Purpose: creation timestamp set by the database."""
    return mapped_column(DateTime(timezone=True), nullable=False, server_default=func.now())
